}

pub fn getBuffer(client: *IOWriter) []const u8 {
        const result = client.getBufferImpl();
        if (comptime bun.Environment.isWindows) {
            _ = client.winbuf.clearRetainingCapacity();
            _ = bun.handleOom(client.winbuf.appendSlice(bun.default_allocator, result));
            return client.winbuf.items;
        }
        _ = log("IOWriter(0x{x}, fd={f}) getBuffer = {d} bytes", .{ @intFromPtr(client), client.fd, result.len });
        return result;
}

pub fn getBufferImpl(client: *IOWriter) []const u8 {
        const writer = brk: {
        if ((client.writer_idx >= client.writers.len())) {
            _ = log("IOWriter(0x{x}, fd={f}) getBufferImpl all writes done", .{ @intFromPtr(client), client.fd });
            return "";
        }
        _ = log("IOWriter(0x{x}, fd={f}) getBufferImpl idx={d} writer_len={d}", .{ @intFromPtr(client), client.fd, client.writer_idx, client.writers.len() });
        var writer = client.writers.get(client.writer_idx);
        _ = &writer;
        if ((!writer.isDead())) {
            break :brk writer;
        }
        _ = log("IOWriter(0x{x}, fd={f}) skipping dead", .{ @intFromPtr(client), client.fd });
        _ = client.skipDead();
        if ((client.writer_idx >= client.writers.len())) {
            _ = log("IOWriter(0x{x}, fd={f}) getBufferImpl all writes done", .{ @intFromPtr(client), client.fd });
            return "";
        }
        writer = client.writers.get(client.writer_idx);
        break :brk writer;
};
        _ = log("IOWriter(0x{x}, fd={f}) getBufferImpl writer_len={} writer_written={}", .{ @intFromPtr(client), client.fd, writer.len, writer.written });
        const remaining = (writer.len - writer.written);
        if (bun.Environment.allow_assert) {
            _ = assert((!(writer.len == writer.written)));
        }
        return client.buf.items[client.total_bytes_written..(client.total_bytes_written + remaining)];
}

pub fn bump(client: *IOWriter, current_writer: *Writer) Yield {
        _ = log("IOWriter(0x{x}, fd={f}) bump(0x{x} {s})", .{ @intFromPtr(client), client.fd, @intFromPtr(current_writer), @tagName(current_writer.ptr.ptr.tag()) });
        const is_dead = current_writer.isDead();
        const written = current_writer.written;
        const child_ptr = current_writer.ptr;
        if (is_dead) {
            _ = client.skipDead();
        } else {
            if (bun.Environment.allow_assert) {
                if ((!is_dead)) {
                    _ = assert((current_writer.written == current_writer.len));
                }
            }
            client.writer_idx = (client.writer_idx + 1);
        }
        if ((client.writer_idx >= client.writers.len())) {
            _ = log("IOWriter(0x{x}, fd={f}) all writers complete: truncating", .{ @intFromPtr(client), client.fd });
            _ = client.buf.clearRetainingCapacity();
            client.writer_idx = 0;
            _ = client.writers.clearRetainingCapacity();
            client.total_bytes_written = 0;
        } else {
            if ((client.total_bytes_written >= SHRINK_THRESHOLD)) {
                const slice = client.buf.items[client.total_bytes_written..];
                const remaining_len = slice.len;
                _ = log("IOWriter(0x{x}, fd={f}) exceeded shrink threshold: truncating (new_len={d}, writer_starting_idx={d})", .{ @intFromPtr(client), client.fd, remaining_len, client.writer_idx });
                if ((slice.len == 0)) {
                    _ = client.buf.clearRetainingCapacity();
                    client.total_bytes_written = 0;
                } else {
                    _ = bun.copy(u8, client.buf.items[0..remaining_len], slice);
                    client.buf.items.len = remaining_len;
                    client.total_bytes_written = 0;
                }
                _ = client.writers.truncate(client.writer_idx);
                client.writer_idx = 0;
                if (bun.Environment.allow_assert) {
                    if ((client.writers.len() > 0)) {
                        const first = client.writers.getConst(client.writer_idx);
                        _ = assert((client.buf.items.len >= first.len));
                    }
                }
            }
        }
        if ((!is_dead)) {
            return child_ptr.onIOWriterChunk(written, null);
        }
        return .done;
}

pub fn enqueueFile(client: *IOWriter) Yield {
        if (client.is_writing) {
            return .suspended;
        }
        client.started = true;
        _ = client.setWriting(true);
        return client.doFileWrite();
}

pub fn enqueueInternal(client: *IOWriter) Yield {
        _ = bun.assert((!client.flags.broken_pipe));
        if (((!client.flags.pollable) and bun.Environment.isPosix)) {
            return client.enqueueFile();
        }
        switch (client.write()) {
.suspended => {
return .suspended;
},
.is_actually_file => {
_ = bun.assert(bun.Environment.isPosix);
        return client.enqueueFile();
},
.failed => {
return .failed;
},
}
}

pub fn handleBrokenPipe(client: *IOWriter, ptr: ChildPtr) ?Yield {
        if (client.flags.broken_pipe) {
            const e: jsc.SystemError = bun.sys.Error.fromCode(.PIPE, .write).toSystemError();
            _ = log("IOWriter(0x{x}, fd={f}) broken pipe {s}(0x{x})", .{ @intFromPtr(client), client.fd, @tagName(ptr.ptr.tag()), @intFromPtr(ptr.ptr.ptr()) });
            return .{ .on_io_writer_chunk = .{ .child = ptr.asAnyOpaque(), .written = 0, .err = e } };
        }
        return null;
}

pub fn enqueue(client: *IOWriter, ptr: anytype, bytelist: ?*bun.ByteList, buf: []const u8) Yield {
        const childptr = (if ((@TypeOf(ptr) == ChildPtr)) ptr else ChildPtr.init(ptr));
        if (client.handleBrokenPipe(childptr)) |yield| {
            _ = &yield;
            return yield;
        }
        if ((buf.len == 0)) {
            _ = log("IOWriter(0x{x}, fd={f}) enqueue EMPTY", .{ @intFromPtr(client), client.fd });
            return .{ .on_io_writer_chunk = .{ .child = childptr.asAnyOpaque(), .written = 0, .err = null } };
        }
        const writer: Writer = .{ .ptr = childptr, .len = buf.len, .bytelist = bytelist };
        _ = log("IOWriter(0x{x}, fd={f}) enqueue(0x{x} {s}, buf_len={d}, buf={s}, writer_len={d})", .{ @intFromPtr(client), client.fd, @intFromPtr(writer.rawPtr()), @tagName(writer.ptr.ptr.tag()), buf.len, buf[0..@min(128, buf.len)], (client.writers.len() + 1) });
        _ = bun.handleOom(client.buf.appendSlice(bun.default_allocator, buf));
        _ = client.writers.append(writer);
        return client.enqueueInternal();
}

pub fn enqueueFmtBltn(self: *IOWriter, ptr: anytype, bytelist: ?*bun.ByteList, comptime kind: ?Interpreter.Builtin.Kind, comptime fmt_: []const u8, args: anytype) Yield {
        const cmd_str = (comptime (if (kind) |k| (@tagName(k) ++ ": ") else ""));
        const fmt__ = (cmd_str ++ fmt_);
        return self.enqueueFmt(ptr, bytelist, fmt__, args);
}

pub fn enqueueFmt(self: *IOWriter, ptr: anytype, bytelist: ?*bun.ByteList, comptime fmt: []const u8, args: anytype) Yield {
        var buf_writer = self.buf.writer(bun.default_allocator);
        _ = &buf_writer;
        const start = self.buf.items.len;
        _ = bun.handleOom(buf_writer.print(fmt, args));
        const childptr = (if ((@TypeOf(ptr) == ChildPtr)) ptr else ChildPtr.init(ptr));
        if (self.handleBrokenPipe(childptr)) |yield| {
            _ = &yield;
            return yield;
        }
        const end = self.buf.items.len;
        const writer: Writer = .{ .ptr = childptr, .len = (end - start), .bytelist = bytelist };
        _ = log("IOWriter(0x{x}, fd={f}) enqueue(0x{x} {s}, {s})", .{ @intFromPtr(self), self.fd, @intFromPtr(writer.rawPtr()), @tagName(writer.ptr.ptr.tag()), self.buf.items[start..end] });
        _ = self.writers.append(writer);
        return self.enqueueInternal();
}

pub fn asyncDeinit(self: *IOWriter) void {
        _ = debug("IOWriter(0x{x}, fd={f}) asyncDeinit", .{ @intFromPtr(self), self.fd });
        _ = bun.assert((!self.is_writing));
        if ((!self.started)) {
            _ = self.deinitOnMainThread();
            return;
        }
        _ = self.async_deinit.enqueue();
}

pub fn deinitOnMainThread(client: *IOWriter) void {
        _ = debug("IOWriter(0x{x}, fd={f}) deinit", .{ @intFromPtr(client), client.fd });
        if (bun.Environment.allow_assert) {
            _ = client.ref_count.assertNoRefs();
        }
        _ = client.buf.deinit(bun.default_allocator);
        _ = client.writers.deinit();
        if (client.err) |*e| {
            _ = &e;
            _ = (e.*).deref();
        }
        if (comptime bun.Environment.isPosix) {
            if ((client.writer.handle == .poll)) {
                _ = client.writer.handle.closeImpl(null, .{}, false);
            }
        } else {
            _ = client.writer.close();
            _ = client.winbuf.deinit(bun.default_allocator);
        }
        if (client.fd.isValid()) {
            _ = client.fd.close();
        }
        _ = client.writer.disableKeepingProcessAlive(client.evtloop);
        _ = bun.destroy(client);
}

pub fn isLastIdx(client: *IOWriter, idx: usize) bool {
        return (idx == (client.writers.len() -| 1));
}

pub inline fn setWriting(client: *IOWriter, writing: bool) void {
        if (bun.Environment.isWindows) {
            _ = log("IOWriter(0x{x}, fd={f}) setWriting({})", .{ @intFromPtr(client), client.fd, writing });
            client.is_writing = writing;
        }
}

pub fn runFromMainThread(self: *IOWriter) void {
    _ = &self;
}

pub fn runFromMainThreadMini(self: *IOWriter, _: *void) void {
    _ = &self;
}

pub fn tryWriteWithWriteFn(fd: bun.FD, buf: []const u8, comptime write_fn: *const fn (bun.FD, []const u8) bun.sys.Maybe(usize)) bun.io.WriteResult {
        var offset: usize = 0;
        _ = &offset;
        while ((offset < buf.len)) {
            switch (write_fn(fd, buf[offset..])) {
.err => |e| {
if ((e).?.isRetry()) {
                return .{ .pending = offset };
            }
            return .{ .err = e };
},
.result => |wrote| {
offset = (offset + wrote);
            if ((wrote == 0)) {
                return .{ .done = offset };
            }
},
}
        }
        return .{ .wrote = offset };
}

pub fn drainBufferedData(parent: *IOWriter, max_write_size: usize, received_hup: bool) bun.io.WriteResult {
        _ = bun.assert(bun.Environment.isPosix);
        _ = &received_hup;
        const buf = parent.getBuffer();
        const trimmed = (if (((max_write_size < buf.len) and (max_write_size > 0))) buf[0..max_write_size] else buf);
        var drained: usize = 0;
        _ = &drained;
        while ((drained < trimmed.len)) {
            const attempt = tryWriteWithWriteFn((parent.fd.get()).?, buf, bun.sys.write);
            switch (attempt) {
.pending => |pending| {
drained = (drained + pending);
            return .{ .pending = drained };
},
.wrote => |amt| {
drained = (drained + amt);
},
.err => |e| {
if ((drained > 0)) {
                _ = onError(parent, e);
                return .{ .wrote = drained };
            } else {
                return .{ .err = e };
            }
},
.done => |amt| {
drained = (drained + amt);
            return .{ .done = drained };
},
}
        }
        return .{ .wrote = drained };
}
pub const RefCount = bun.ptr.RefCount(@This(), "ref_count", asyncDeinit, .{});
pub const ref = RefCount.ref;
pub const deref = RefCount.deref;
pub const WriteStatus = enum {
    suspended,
    failed,
    is_actually_file,
};
